/* Royal Gujarati Heritage — intentionally dependency-free JavaScript */
'use strict';

/* PHOTO CONFIGURATION
 * Leave a value as null to display its elegant placeholder.
 * When photographs are ready, copy their optimized .webp files to assets/
 * and replace null with the corresponding path. Examples:
 * 'priyanka-karan-main': 'assets/priyanka-karan-main.webp'
 * 'priyanka-karan-01': 'assets/priyanka-karan-01.webp'
 * The photographs are NEVER edited or generated by this script.
 */
const PHOTO_CONFIG = {
  'priyanka-karan-main': null,
  'trupti-dipak-main': 'assets/trupti-dipak-main.webp',
  'priyanka-karan-01': null,
  'priyanka-karan-02': null,
  'priyanka-karan-03': null,
  'priyanka-karan-04': null,
  'trupti-dipak-01': 'assets/trupti-dipak-01.webp',
  'trupti-dipak-02': 'assets/trupti-dipak-02.webp',
  'trupti-dipak-03': 'assets/trupti-dipak-03.webp',
  'trupti-dipak-04': 'assets/trupti-dipak-04.webp',
  'sisters-together': null
};

const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
const opening = document.getElementById('opening-screen');
const siteShell = document.getElementById('site-shell');
const openButton = document.getElementById('open-invitation');
let invitationOpened = false;
let toastTimeout;

// Keep the invitation underneath completely non-interactive until the cover opens.
if (opening && siteShell) {
  siteShell.inert = true;
  if ('scrollRestoration' in history) history.scrollRestoration = 'manual';
  window.scrollTo(0, 0);
}

function showToast(message) {
  const toast = document.getElementById('toast');
  if (!toast) return;
  window.clearTimeout(toastTimeout);
  toast.textContent = message;
  toast.classList.add('is-visible');
  toastTimeout = window.setTimeout(() => toast.classList.remove('is-visible'), 3500);
}

function revealMain() {
  if (invitationOpened) return;
  invitationOpened = true;
  document.body.classList.remove('opening-active');
  siteShell.inert = false;
  opening.hidden = true;
  window.scrollTo(0, 0);
  document.querySelector('.site-header .brand')?.focus({ preventScroll: true });
  enableScrollReveals();
}

if (openButton) {
  openButton.addEventListener('click', () => {
    if (opening.classList.contains('is-opening')) return;
    if (reducedMotion.matches) {
      revealMain();
      return;
    }
    opening.classList.add('is-opening');
    // 1.3 seconds for the door reveal, then a soft crossfade.
    window.setTimeout(() => opening.classList.add('is-dismissing'), 1290);
    window.setTimeout(revealMain, 1830);
  });
}

// Do not hide any content when IntersectionObserver is absent or animations are disabled.
function enableScrollReveals() {
  if (!('IntersectionObserver' in window) || reducedMotion.matches) return;
  const revealed = document.querySelectorAll('.reveal');
  const observer = new IntersectionObserver((entries) => {
    for (const entry of entries) {
      if (entry.isIntersecting) {
        entry.target.classList.add('is-visible');
        observer.unobserve(entry.target);
      }
    }
  }, { rootMargin: '0px 0px -35px 0px', threshold: 0.07 });
  document.body.classList.add('js-motion');
  revealed.forEach(el => observer.observe(el));
}

// UTC 06:15 = Asia/Kolkata (IST, UTC+05:30) 11:45 AM, 22 November 2026.
const COUNTDOWN_TARGET = Date.parse('2026-11-22T06:15:00Z');
const UNITS = ['days','hours','minutes','seconds'];
const countdownNodes = Object.fromEntries(UNITS.map(unit => [unit, document.querySelector(`[data-count="${unit}"]`)]));
let priorValues = {};
function updateCountdown() {
  const remaining = Math.max(0, COUNTDOWN_TARGET - Date.now());
  const totalSeconds = Math.floor(remaining / 1000);
  const values = {
    days: Math.floor(totalSeconds / 86400),
    hours: Math.floor((totalSeconds % 86400) / 3600),
    minutes: Math.floor((totalSeconds % 3600) / 60),
    seconds: totalSeconds % 60
  };
  for (const unit of UNITS) {
    const face = countdownNodes[unit];
    if (!face) continue;
    const formatted = String(values[unit]).padStart(2, '0');
    if (priorValues[unit] !== formatted) {
      face.querySelector('.flip-number').textContent = formatted;
      if (priorValues[unit] !== undefined && !reducedMotion.matches) {
        // Animate only changed units. A seconds tick never flips the rest of the clock.
        face.classList.remove('is-flipping');
        void face.offsetWidth;
        face.classList.add('is-flipping');
      }
      priorValues[unit] = formatted;
    }
  }
  const celebration = document.getElementById('countdown-celebration');
  if (celebration) celebration.hidden = remaining !== 0;
}
updateCountdown();
window.setInterval(updateCountdown, 1000);

// Share the actual hosted invitation, or copy its URL if Web Share is unsupported.
async function shareInvitation() {
  const url = window.location.href.split('#')[0];
  const shareData = {
    title: 'Priyanka & Karan · Trupti & Dipak — Wedding Invitation',
    text: 'Join us for a beautiful double-wedding celebration on 21 & 22 November 2026 in Bhavnagar!',
    url
  };
  if (navigator.share) {
    try { await navigator.share(shareData); return; }
    catch (error) { if (error.name === 'AbortError') return; }
  }
  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(url);
    } else {
      const temp = document.createElement('textarea');
      temp.value = url; temp.style.position = 'fixed'; temp.style.opacity = '0';
      document.body.appendChild(temp); temp.select();
      if (!document.execCommand('copy')) throw new Error('Clipboard unavailable');
      temp.remove();
    }
    showToast('Invitation link copied!');
  } catch (_) { showToast('Please copy the website address from your browser.'); }
}
document.getElementById('share-invitation')?.addEventListener('click', shareInvitation);
document.getElementById('header-share')?.addEventListener('click', shareInvitation);

// A complete photograph view, dormant until the actual photo paths are configured.
const loadedImages = new Map();
for (const slot of document.querySelectorAll('.photo-slot')) {
  const key = slot.dataset.photo;
  const path = PHOTO_CONFIG[key];
  if (!path || typeof path !== 'string') continue;
  const image = slot.querySelector('.photo-image');
  if (!image) continue;
  image.onload = () => {
    image.hidden = false;
    slot.classList.add('has-photo');
    loadedImages.set(key, { key, url: image.src, alt: image.alt, slot });
    if (slot.matches('button.gallery-tile')) {
      slot.disabled = false;
      slot.setAttribute('aria-label', image.alt + ', open larger photograph');
    }
  };
  image.onerror = () => {
    image.hidden = true;
    slot.classList.remove('has-photo');
  };
  image.hidden = false;  // Hidden lazy images can otherwise remain unrequested.
  image.decoding = 'async';
  if (slot.classList.contains('hero-portrait')) image.loading = 'eager';
  image.src = path;
}

const dialog = document.getElementById('photo-dialog');
const dialogImage = document.getElementById('dialog-photo');
const dialogCaption = document.getElementById('dialog-caption');
const previousButton = document.getElementById('dialog-prev');
const nextButton = document.getElementById('dialog-next');
let activeGallery = [];
let activeIndex = 0;
function showDialogImage(index) {
  if (!activeGallery.length) return;
  activeIndex = (index + activeGallery.length) % activeGallery.length;
  const entry = activeGallery[activeIndex];
  dialogImage.src = entry.url;
  dialogImage.alt = entry.alt;
  dialogCaption.textContent = `${entry.alt} · ${activeIndex + 1} of ${activeGallery.length}`;
  previousButton.hidden = activeGallery.length < 2;
  nextButton.hidden = activeGallery.length < 2;
}
for (const gallery of document.querySelectorAll('.gallery-grid')) {
  gallery.addEventListener('click', (event) => {
    const tile = event.target.closest('.gallery-tile.has-photo');
    if (!tile || !gallery.contains(tile) || !dialog?.showModal) return;
    activeGallery = [...gallery.querySelectorAll('.gallery-tile.has-photo')].map(el => loadedImages.get(el.dataset.photo)).filter(Boolean);
    const index = activeGallery.findIndex(el => el.key === tile.dataset.photo);
    if (index < 0) return;
    showDialogImage(index);
    dialog.showModal();
  });
}
previousButton?.addEventListener('click', () => showDialogImage(activeIndex - 1));
nextButton?.addEventListener('click', () => showDialogImage(activeIndex + 1));
document.getElementById('dialog-close')?.addEventListener('click', () => dialog.close());
dialog?.addEventListener('click', (event) => { if (event.target === dialog) dialog.close(); });
dialog?.addEventListener('keydown', (event) => {
  if (event.key === 'ArrowLeft') { event.preventDefault(); showDialogImage(activeIndex - 1); }
  if (event.key === 'ArrowRight') { event.preventDefault(); showDialogImage(activeIndex + 1); }
});
